import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import path from "node:path";
import { gitEnvironment, root } from "./process.ts";

// The committed Contracts identity: generated by tools/ArcForges.Cloud.Generation from the restored NuGet package (S33(3)(a)).
export const contractsIdentityRecord = "eng/generated/contracts-identity.json";
const legacyContractsSource = "packages/contracts/source.json";
const goDependencyRecord = "center/dependencies.json";
const goContractsModule = "github.com/ArcForges/Contracts/go";
export const axes = [
  "AppVersion",
  "ContractSet",
  "CapabilityVersion",
  "NativeFormatVersion",
  "StorageSchemaVersion",
  "NativeAbiVersion",
  "PolicySchemaVersion",
  "ExtensionProtocolVersion",
  "PackageVersion",
];
const kinds = [
  "release",
  "contracts",
  "declarations",
  "declarations",
  "migrations",
  "native-abi",
  "declarations",
  "declarations",
  "packages",
];
function object(value: unknown): Record<string, unknown> {
  assert(value && typeof value === "object" && !Array.isArray(value));
  return value as Record<string, unknown>;
}
function string(value: unknown): string {
  assert.equal(typeof value, "string");
  return value as string;
}
function array(value: unknown): unknown[] {
  assert(Array.isArray(value));
  return value;
}
function digest(value: string) {
  return createHash("sha256").update(value).digest("hex");
}

function readGoModules(input: Record<string, unknown>, read: (source: string) => string) {
  assert.equal(input.schemaVersion, 1);
  const inputs = object(input.inputs);
  const moduleFile = read("center/go.mod");
  const sumFile = read("center/go.sum");
  assert.equal(digest(moduleFile), inputs["go.mod"], "Go module file differs from its admission");
  assert.equal(digest(sumFile), inputs["go.sum"], "Go sum file differs from its admission");
  const sums = new Set(sumFile.split(/\r?\n/u));
  const modules = array(input.runtimeModules).map((row) => {
    const module = object(row);
    const path = string(module.path);
    const version = string(module.version);
    const sum = string(module.sum);
    const goModSum = string(module.goModSum);
    const repository = string(module.repository);
    const commit = string(module.commit);
    assert.match(path, /^[A-Za-z0-9_.-]+(?:\/[A-Za-z0-9_.-]+)+$/u);
    assert.match(version, /^v\d+\.\d+\.\d+(?:[-+][A-Za-z0-9.-]+)?$/u);
    assert.match(sum, /^h1:[A-Za-z0-9+/]{43}=$/u);
    assert.match(goModSum, /^h1:[A-Za-z0-9+/]{43}=$/u);
    assert(repository.startsWith("https://"));
    assert.match(commit, /^[a-f0-9]{40}$/u);
    assert(sums.has(`${path} ${version} ${sum}`), "Go module archive hash is missing from go.sum");
    assert(
      sums.has(`${path} ${version}/go.mod ${goModSum}`),
      "Go module metadata hash is missing from go.sum",
    );
    return { path, version, sum, goModSum, repository, commit };
  });
  assert.equal(
    new Set(modules.map((module) => module.path)).size,
    modules.length,
    "Duplicate Go runtime module",
  );
  const contracts = modules.find((module) => module.path === goContractsModule);
  assert(contracts, "The admitted Go runtime closure must include Contracts");
  assert.equal(contracts.repository, "https://github.com/ArcForges/Contracts");
  const pins = [
    ...moduleFile.matchAll(
      /^\s*(?:require\s+)?github\.com\/ArcForges\/Contracts\/go[ \t]+(\S+).*$/gmu,
    ),
  ];
  assert.equal(pins.length, 1, "The Go module file must contain one exact Contracts pin");
  assert.equal(pins[0]?.[1], contracts.version, "Go Contracts pin differs from its admission");
  return { contracts, modules };
}

export function resolveAxes(catalog: unknown, read: (source: string) => string) {
  const document = object(catalog);
  assert.equal(document.schemaVersion, 1);
  assert.equal(document.owner, "Cloud");
  const definitions = object(document.axes);
  assert.deepEqual(Object.keys(definitions).sort(), [...axes].sort());
  const result: Record<string, unknown> = {};
  let go: ReturnType<typeof readGoModules> | undefined;
  for (const [index, name] of axes.entries()) {
    const definition = object(definitions[name]);
    const kind = string(definition.kind);
    assert.equal(kind, kinds[index]);
    if (definition.absence !== undefined) {
      assert(
        Object.keys(definition).every((key) =>
          ["kind", "absence", "reason", "producer"].includes(key),
        ),
      );
      assert(["not-produced", "not-applicable"].includes(string(definition.absence)));
      assert(string(definition.reason).trim());
      if (definition.absence === "not-produced") assert(string(definition.producer).trim());
      result[name] = {
        status: definition.absence,
        reason: definition.reason,
        ...(definition.producer === undefined ? {} : { producer: definition.producer }),
      };
      continue;
    }
    assert(Object.keys(definition).every((key) => ["kind", "sources"].includes(key)));
    const values = new Map<string, Record<string, unknown>>();
    for (const item of array(definition.sources)) {
      const sourcePath = string(item);
      assert(
        !/[\\:]/u.test(sourcePath) &&
          sourcePath.split("/").every((part) => part && part !== "." && part !== ".."),
      );
      const content = read(sourcePath).replaceAll("\r\n", "\n");
      const source = { path: sourcePath, sha256: digest(content) };
      const add = (subject: string, version: string, evidence?: Record<string, unknown>) => {
        assert(subject.trim() && /^[0-9]+(?:\.[0-9]+)*(?:[-+][A-Za-z0-9.-]+)?$/u.test(version));
        assert(!values.has(subject), "Duplicate version subject");
        values.set(subject, {
          subject,
          version,
          source,
          ...evidence,
        });
      };
      if (kind === "native-abi") {
        const major = /#define\s+ARC_ABI_MAJOR\s+(\d+)/u.exec(content)?.[1];
        const minor = /#define\s+ARC_ABI_MINOR\s+(\d+)/u.exec(content)?.[1];
        assert(major && minor);
        add(sourcePath, `${major}.${minor}`);
        continue;
      }
      const input = object(JSON.parse(content));
      if (sourcePath === goDependencyRecord && (kind === "contracts" || kind === "packages")) {
        go ??= readGoModules(input, read);
        if (kind === "contracts") {
          // The Go admission binds the published module, not a combined protobuf descriptor.
          add(`pkg:go/${go.contracts.path}`, go.contracts.version.slice(1), {
            goModule: go.contracts,
          });
        } else {
          for (const module of go.modules) add(`pkg:go/${module.path}`, module.version.slice(1));
        }
        continue;
      }
      if (kind === "contracts") {
        if (sourcePath === legacyContractsSource) {
          const pins = read("Directory.Packages.props");
          const pinned = /Include="ArcForges.Contracts.PublicApi" Version="([^"]+)"/u.exec(
            pins,
          )?.[1];
          assert(pinned);
          assert.equal(input.version, pinned);
        }
        // The current Contracts receipt lists every schema source instead of one schema name; the
        // Hello contract this service serves is identified by its source entry.
        const named =
          input.schema === undefined
            ? helloSchemaOf(object(input.schemaSources))
            : string(input.schema);
        const schema = /^([a-zA-Z0-9_.]+)\.v([1-9][0-9]*)$/u.exec(named);
        assert(schema?.[1] && schema[2]);
        assert.match(string(input.descriptorSha256), /^[a-f0-9]{64}$/u);
        assert.equal(input.dirty, false);
        add(schema[1], schema[2], { descriptorSha256: string(input.descriptorSha256) });
      } else if (kind === "packages") {
        if (input.lockfileVersion !== undefined) {
          for (const [name, value] of Object.entries(object(input.packages)))
            if (name) add(`pkg:npm/${name}`, string(object(value).version));
        } else {
          for (const [framework, dependencies] of Object.entries(object(input.dependencies)))
            for (const [name, value] of Object.entries(object(dependencies))) {
              const dependency = object(value);
              if (dependency.type !== "Project")
                add(`pkg:nuget/${name}?target=${framework}`, string(dependency.resolved));
            }
        }
      } else {
        const declarations = array(input[kind === "migrations" ? "migrations" : "versions"]);
        for (const value of kind === "migrations" ? declarations.slice(-1) : declarations) {
          const declaration = object(value);
          add(string(declaration.subject), string(declaration.version));
        }
      }
    }
    assert(kind === "packages" || values.size > 0);
    result[name] = {
      status: "present",
      values: [...values.keys()].sort().map((key) => values.get(key)),
    };
  }
  return result;
}

export function sourceBuild(commit: string, epoch: number, dirty: boolean, env: NodeJS.ProcessEnv) {
  assert.match(commit, /^[a-f0-9]{40}$/u);
  assert(Number.isSafeInteger(epoch) && epoch > 0);
  const ci = env.GITHUB_ACTIONS === "true";
  const run = ci ? env.GITHUB_RUN_ID : null;
  const attempt = ci ? Number(env.GITHUB_RUN_ATTEMPT) : null;
  if (ci) {
    assert.equal(dirty, false);
    assert.equal(env.GITHUB_SHA, commit);
    assert.equal(env.GITHUB_REPOSITORY, "ArcForges/Cloud");
    assert.match(run ?? "", /^[1-9][0-9]*$/u);
    assert(Number.isSafeInteger(attempt) && attempt !== null && attempt > 0);
  }
  return {
    sourceCommit: commit,
    dirty,
    kind: ci ? "ci" : "local",
    buildId: ci ? `${run}.${attempt}` : `local.${commit}`,
    runId: run,
    runAttempt: attempt,
    pipelineRun: ci ? `https://github.com/ArcForges/Cloud/actions/runs/${run}` : null,
    sourceDateEpoch: epoch,
  };
}

/**
 * The run that produced the candidate. A main push builds and deploys its own candidate, so the producer is this run. A proof
 * deployment dispatch builds none: its gate job (eng/verification/proof-gate.ts) found the successful main-push run of the same
 * commit and the deploy job names that run in ARCFORGES_CANDIDATE_RUN_ID, _RUN_NUMBER and _RUN_ATTEMPT. Only a workflow_dispatch may
 * name another run, and only with all three.
 */
export const producerRunVariables = [
  "ARCFORGES_CANDIDATE_RUN_ID",
  "ARCFORGES_CANDIDATE_RUN_NUMBER",
  "ARCFORGES_CANDIDATE_RUN_ATTEMPT",
] as const;

export function candidateEnvironment(version: string, environment: NodeJS.ProcessEnv) {
  const producer = { ...environment };
  if (producer.GITHUB_ACTIONS === "true") {
    const named = producerRunVariables.map((name) => environment[name] ?? "");
    if (named.some((value) => value !== "")) {
      assert.equal(
        environment.GITHUB_EVENT_NAME,
        "workflow_dispatch",
        "Only the proof dispatch deploys the candidate of another run.",
      );
      assert(
        named.every((value) => /^[1-9][0-9]{0,15}$/u.test(value)),
        "Name the candidate's run id, number and attempt together.",
      );
      [producer.GITHUB_RUN_ID, producer.GITHUB_RUN_NUMBER, producer.GITHUB_RUN_ATTEMPT] = named;
    }
    const release = /^0\.1\.0-ci\.([1-9][0-9]*)\.([1-9][0-9]*)$/u.exec(version);
    assert(release?.[1] && release[2]);
    assert.equal(release[1], producer.GITHUB_RUN_NUMBER);
    assert(
      Number(release[2]) <= Number(producer.GITHUB_RUN_ATTEMPT),
      "Candidate is from a future attempt",
    );
    producer.GITHUB_RUN_ATTEMPT = release[2];
  }
  return producer;
}

export function expectedIdentity(version: string) {
  const git = (...args: string[]) =>
    execFileSync("git", args, {
      cwd: root,
      encoding: "utf8",
      windowsHide: true,
      timeout: 30000,
      env: gitEnvironment(),
    }).trim();
  const commit = git("rev-parse", "HEAD");
  const producer = candidateEnvironment(version, process.env);
  const build = sourceBuild(
    commit,
    Number(git("show", "-s", "--format=%ct", commit)),
    git("status", "--porcelain").length > 0,
    producer,
  );
  const read = (name: string) => {
    if (name === "assembly/release.json")
      return JSON.stringify({ versions: [{ subject: "Cloud", version }] });
    // CLOUD.84 S33(3)(a): the committed copy of the restored NuGet Contracts source.json, byte-checked by a C# test and by generate --check.
    if (name === legacyContractsSource)
      return readFileSync(path.join(root, contractsIdentityRecord), "utf8");
    return readFileSync(path.join(root, name), "utf8");
  };
  return {
    schema: "arcforges.build-identity.v1",
    owner: "Cloud",
    artifact: { id: "Cloud", version },
    build,
    axes: resolveAxes(JSON.parse(read("eng/version-sources.json")), read),
  };
}

function helloSchemaOf(sources: Record<string, unknown>) {
  assert.match(string(sources["public/proto/arcforges/hello/v1/hello.proto"]), /^[a-f0-9]{64}$/u);
  return "arcforges.hello.v1";
}
export type Identity = ReturnType<typeof expectedIdentity>;
export function verifyIdentity(actual: unknown, version: string) {
  assert.deepEqual(
    actual,
    expectedIdentity(version),
    "Built identity differs from independent source/run/version inputs",
  );
}
export function imageBuildVariables(identity: Identity) {
  const build = identity.build;
  return {
    SOURCE_REVISION: build.sourceCommit + (build.dirty ? "-dirty" : ""),
    SOURCE_COMMIT: build.sourceCommit,
    SOURCE_DIRTY: String(build.dirty),
    APP_VERSION: identity.artifact.version,
    BUILD_KIND: build.kind,
    BUILD_ID: build.buildId,
    PIPELINE_RUN: build.pipelineRun ?? "local",
    SOURCE_EPOCH: String(build.sourceDateEpoch),
  };
}
export function verifyHealthIdentity(health: unknown, identity: Identity) {
  const actual = object(health);
  assert.deepEqual(actual.build, identity.build, "Running compiled build identity differs");
  assert.deepEqual(actual.artifact, identity.artifact, "Running application release differs");
  const contracts = object(identity.axes.ContractSet);
  if (
    contracts.status === "present" &&
    array(contracts.values).some((value) => object(value).subject === `pkg:go/${goContractsModule}`)
  ) {
    assert.equal(actual.runtime, "go");
    assert.equal(actual.nativeAot, false);
  }
}
